static lv_obj_t *s_desc_box;    /* 白卡片（手动定位/定高，无 flex） */
static lv_obj_t *s_issue_desc;
static lv_obj_t *s_advice;
static lv_timer_t *s_layout_timer;   /* 首帧后重算一次卡片高度（兜底） */

/* 全手动几何常量（勿改回 flex/百分比——历史教训见文件头） */

#define DIAG_CARD_X     16                    /* 卡片 x：(480-448)/2 */
#define DIAG_CARD_Y     (TP_TOP_BAR_H + 14)   /* 卡片 y：导航栏下方 */
#define DIAG_CARD_W     448                   /* 卡片宽 */
#define DIAG_TEXT_W     416                   /* 文字宽 = 448 - 2×16 */
#define DIAG_PAD        16                    /* 文字距卡片边（内边距） */
#define DIAG_GAP        8                     /* 问题段与建议段间距 */
#define DIAG_MAX_H      (320 - DIAG_CARD_Y - 8)  /* 卡片高上限（超高可滚） */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void diag_on_back(lv_event_t *e)
{
  (void)e;
  ui_app_pop_screen();
}

/* 页面销毁：删一次性定时器（voice 页同款 UAF 教训） */

static void diag_on_delete(lv_event_t *e)
{
  (void)e;

  if (s_layout_timer != NULL)
    {
      lv_timer_delete(s_layout_timer);
      s_layout_timer = NULL;
    }

  s_desc_box = NULL;
  s_issue_desc = NULL;
  s_advice = NULL;
}

/* 按文本实测高度摆布局：advice 放 issue 下方，卡片高度随内容伸缩 */

static void diag_relayout(void)
{
  static bool s_dbg_once;
  int32_t ih;
  int32_t ah;
  int32_t ch;

  if (s_desc_box == NULL)
    {
      return;
    }

  /* 强制先按当前文本算一次折行高度 */
  lv_obj_update_layout(s_desc_box);

  ih = (s_issue_desc != NULL) ? lv_obj_get_height(s_issue_desc) : 0;
  if (ih < 0)
    {
      ih = 0;
    }

  if (!s_dbg_once && s_issue_desc != NULL)
    {
      /* 一次性诊断：确认 label 实际宽（416 = 正常；~16 = 仍有塌缩） */
      printf("[Diag] issue w=%d h=%d\n",
             (int)lv_obj_get_width(s_issue_desc), (int)ih);
      s_dbg_once = true;
    }

  if (s_advice != NULL &&
      lv_label_get_text(s_advice) != NULL &&
      lv_label_get_text(s_advice)[0] != '\0')
    {
      lv_obj_clear_flag(s_advice, LV_OBJ_FLAG_HIDDEN);
      ah = lv_obj_get_height(s_advice);
      if (ah < 0)
        {
          ah = 0;
        }

      lv_obj_set_pos(s_advice, DIAG_PAD, DIAG_PAD + ih + DIAG_GAP);
      ch = DIAG_PAD * 2 + ih + DIAG_GAP + ah;
    }
  else
    {
      if (s_advice != NULL)
        {
          lv_obj_add_flag(s_advice, LV_OBJ_FLAG_HIDDEN);
        }

      ch = DIAG_PAD * 2 + ih;
    }

  if (ch > DIAG_MAX_H)
    {
      ch = DIAG_MAX_H;   /* 超高：卡片顶格，内容可上下滚动 */
    }

  lv_obj_set_height(s_desc_box, ch);
}

/* 一次性兜底：页面显示后首帧布局已完成，重算一次保证坐标/高度正确 */

static void diag_layout_timer_cb(lv_timer_t *timer)
{
  (void)timer;
  diag_relayout();

  if (s_layout_timer != NULL)
    {
      lv_timer_delete(s_layout_timer);
      s_layout_timer = NULL;
    }
}

