 * ③ AI诊断结果 — 纯绝对定位 + 超高滚动版（2026-09-09 用户定案）
 *
 * 演进：
 *   v1 flex-column+SIZE_CONTENT+PCT → 宽度塌缩逐字竖排（已废弃）
 *   v2 纯绝对定位固定矩形         → 布局稳，但文本长度>固定高时看不全
 *   v3（本版）零 flex/百分比，文字放进【可纵向滚动容器】：
 *      label 宽度固定 448 自动换行、高度随内容自适应（不再写死），
 *      advice 按 issue 实测高度排在下方；内容超高时容器可拖动滚动，
 *      任意长度 AI 回复都能完整显示（配合上游缓冲放大）。
 *  只显示 AI 诊断语句（无图标/emoji/装饰，杜绝豆腐）。
 ****************************************************************************/

#include <lvgl/lvgl.h>
#include <stdio.h>

#include "screen_diagnose.h"
#include "../ui_app.h"
#include "../theme/theme_plant.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *s_scroll;        /* 透明纵向滚动容器（承载两段文字） */
static lv_obj_t *s_issue_desc;    /* AI 诊断描述（自动换行，高自适应） */
static lv_obj_t *s_advice;        /* 养护建议（绿色，排在描述下方） */
static lv_timer_t *s_layout_timer;   /* 首帧后重算 advice 位置（兜底） */

/* 全手动几何常量（勿改回 flex/百分比——历史教训见文件头） */

#define DIAG_X          16
#define DIAG_Y          (TP_TOP_BAR_H + 12)   /* 52：导航栏下方 */
#define DIAG_W          448
#define DIAG_H          (320 - DIAG_Y - 6)    /* 262：滚动可视区高 */
#define DIAG_GAP        10                    /* issue 与 advice 间距 */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void diag_on_back(lv_event_t *e)
{
  (void)e;
  ui_app_pop_screen();
}

/* 页面销毁：删一次性定时器 + 清指针（voice 页同款 UAF 教训） */

static void diag_on_delete(lv_event_t *e)
{
  (void)e;

  if (s_layout_timer != NULL)
    {
      lv_timer_delete(s_layout_timer);
      s_layout_timer = NULL;
    }

  s_scroll = NULL;
  s_issue_desc = NULL;
  s_advice = NULL;
}

/* 按实测文本高度摆放：advice 紧跟 issue 下方（issue 高自动，无需改）。
 * 内容总高 > DIAG_H 时滚动容器自动可拖，文本不丢。 */

static void diag_relayout(void)
{
  int32_t ih;

  if (s_scroll == NULL)
    {
      return;
    }

  /* 强制按当前文本重算 label 高度（WRAP + 固定宽 → 高随行数） */
  lv_obj_update_layout(s_scroll);

  ih = (s_issue_desc != NULL) ? lv_obj_get_height(s_issue_desc) : 0;
  if (ih < 0)
    {
      ih = 0;
    }

  if (s_advice != NULL)
    {
      if (lv_label_get_text(s_advice) != NULL &&
          lv_label_get_text(s_advice)[0] != '\0')
        {
          lv_obj_clear_flag(s_advice, LV_OBJ_FLAG_HIDDEN);
          lv_obj_set_pos(s_advice, 0, ih + DIAG_GAP);
        }
      else
        {
          lv_obj_add_flag(s_advice, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

/* 一次性兜底：页面显示后首帧布局完成，重算一次保证位置正确 */

static void diag_layout_timer_cb(lv_timer_t *timer)
{
  (void)timer;
  diag_relayout();

  if (s_layout_timer != NULL)
    {
      lv_timer_delete(s_layout_timer);
      s_layout_timer = NULL;
    }
}

/* 可换行 label 工厂：固定宽 + 自动高 + LONG_WRAP（绝不塌缩、不截断） */

static lv_obj_t *make_wrap_label(lv_obj_t *parent, const char *text,
                                 lv_color_t color)
{
  lv_obj_t *lab = lv_label_create(parent);

  lv_label_set_text(lab, text != NULL ? text : "");
  lv_obj_set_style_text_font(lab, TP_FONT_BODY, 0);
  lv_obj_set_style_text_color(lab, color, 0);
  lv_obj_set_pos(lab, 0, 0);
  lv_obj_set_width(lab, DIAG_W);
  lv_label_set_long_mode(lab, LV_LABEL_LONG_WRAP);
  lv_obj_set_style_text_line_space(lab, 4, 0);
  return lab;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

lv_obj_t *screen_diagnose_create(void)
{
  lv_obj_t *scr = lv_obj_create(lv_screen_active());
  lv_obj_t *back;
  lv_obj_t *title;

  lv_obj_remove_style_all(scr);
  lv_obj_set_size(scr, 480, 320);
  lv_obj_set_style_bg_color(scr, lv_color_hex(0xeff6ff), 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
  lv_obj_set_style_bg_grad_color(scr, lv_color_hex(TP_CLR_BG_GRAD_A), 0);
  lv_obj_set_style_bg_grad_dir(scr, LV_GRAD_DIR_VER, 0);

  /* 顶部导航（纯文本，无图标字形依赖） */

  back = lv_button_create(scr);
  lv_obj_remove_style_all(back);
  lv_obj_set_size(back, 96, TP_TOP_BAR_H);
  lv_obj_set_pos(back, 0, 0);
  lv_obj_set_style_bg_color(back, lv_color_hex(0x00000000), 0);
  lv_obj_set_style_text_color(back, lv_color_hex(TP_CLR_DATA_BLUE), 0);
  lv_obj_set_style_text_font(back, TP_FONT_TITLE, 0);
  theme_btn_set_text(back, "返回");
  lv_obj_add_event_cb(back, diag_on_back, LV_EVENT_CLICKED, NULL);

  title = lv_label_create(scr);
  lv_label_set_text(title, "识别结果");
  lv_obj_set_style_text_font(title, TP_FONT_TITLE, 0);
  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 8);

  /* 文字滚动容器：透明、固定视口、纵向可滚（内容超高时拖动看全文） */

  s_scroll = lv_obj_create(scr);
  lv_obj_remove_style_all(s_scroll);
  lv_obj_set_pos(s_scroll, DIAG_X, DIAG_Y);
  lv_obj_set_size(s_scroll, DIAG_W, DIAG_H);
  lv_obj_set_scroll_dir(s_scroll, LV_DIR_VER);
  lv_obj_add_flag(s_scroll, LV_OBJ_FLAG_SCROLLABLE);

  /* 问题描述（深色，自动换行 + 高度自适应，绝不截断） */

  s_issue_desc = make_wrap_label(s_scroll, "正在等待识别结果…",
                                 lv_color_hex(TP_CLR_TEXT_MAIN));

  /* 养护建议（绿色；坐标由 diag_relayout 按 issue 高度排到其下方） */

  s_advice = make_wrap_label(s_scroll, "",
                             lv_color_hex(TP_CLR_PRIMARY_GREEN_DARK));

  /* 占位先摆一次；页面显示后再兜底重算 */

  diag_relayout();

  if (s_layout_timer == NULL)
    {
      s_layout_timer = lv_timer_create(diag_layout_timer_cb, 120, NULL);
      lv_timer_set_repeat_count(s_layout_timer, 1);
    }

  /* 页面销毁（返回）时删定时器 + 清指针（防 use-after-free） */

  lv_obj_add_event_cb(scr, diag_on_delete, LV_EVENT_DELETE, NULL);

  return scr;
}

void screen_diagnose_set(lv_obj_t *scr,
                         const char *name, const char *latin,
                         int match, const char *tags,
                         bool issue, const char *issue_desc,
                         const char *advice)
{
  (void)scr;
  (void)name;      /* 只显示 AI 诊断语句 */
  (void)latin;
  (void)match;
  (void)tags;
  (void)issue;

  if (s_issue_desc != NULL)
    {
      lv_label_set_text(s_issue_desc,
                        (issue_desc != NULL && issue_desc[0] != '\0')
                        ? issue_desc : "没看出明显问题，继续用心照顾它就好啦。");
    }

  if (s_advice != NULL)
    {
      lv_label_set_text(s_advice,
                        (advice != NULL && advice[0] != '\0')
                        ? advice : "");
    }

  /* 文本变了 → 重排 advice 位置（label 高度自适应，无需改高） */
  diag_relayout();
}
