      strncpy(g_dev, dev, sizeof(g_dev) - 1);
    }

  if (baudrate > 0)
    {
      g_baudrate = baudrate;
    }

  printf("[SOIL] Initializing: %s @ %d\n", g_dev, g_baudrate);

  /* 打开 UART 设备 */

  g_fd = open(g_dev, O_RDWR | O_NOCTTY);
  if (g_fd < 0)
    {
      printf("[SOIL] Failed to open %s: %d\n", g_dev, errno);
      return -1;
    }

  /* 配置 UART */

  if (soil_sensor_configure_uart(g_fd, g_baudrate) < 0)
